-- S22-AI: parámetros, juicio independiente, cobertura y EKB.
BEGIN;
DO $ekb$ BEGIN IF to_regclass('transversal.error_knowledge') IS NOT NULL THEN INSERT INTO transversal.error_knowledge(codigo,categoria,titulo,descripcion,causa_raiz,prevencion,validacion,severidad,estado,evidencia,lote_origen,source_context,source_ref) VALUES('LF-NUCLEO-S22-REPLAY-HASH-NOTICE','CI_GOVERNANCE','Replay PG17 no expone NOTICE de hashes','Replay PG17 no expone NOTICE de hashes','El log del replay oculta NOTICE; sin hash exacto no hay juicio verificable.','En borrador emitir RAISE EXCEPTION temporal S22xx_HASH_ALL con todos los hashes; leer log y retirar excepción en el push de juicios.','Comprobar marcador en log del PASE y ausencia en candidato final.','High','activo','PR #4789 PASE 45745802735; #4790 PASE 45751164061','S22-AI','LF_NUCLEO','S22-AF/AG') ON CONFLICT(codigo) DO NOTHING; IF NOT EXISTS (SELECT 1 FROM transversal.error_knowledge WHERE codigo='LF-NUCLEO-S22-REPLAY-HASH-NOTICE') THEN RAISE EXCEPTION 'S22AI_EKB_MISSING LF-NUCLEO-S22-REPLAY-HASH-NOTICE'; END IF; END IF; END $ekb$;
DO $ekb$ BEGIN IF to_regclass('transversal.error_knowledge') IS NOT NULL THEN INSERT INTO transversal.error_knowledge(codigo,categoria,titulo,descripcion,causa_raiz,prevencion,validacion,severidad,estado,evidencia,lote_origen,source_context,source_ref) VALUES('LF-NUCLEO-S22-SCOPE-TWINS','PLANNING','Gemelos por módulo cuando el ancestro está vedado','Gemelos por módulo cuando el ancestro está vedado','GLOBAL/CLIENTE/CLIENT_LEGAL alcanzan PANTALLA-36; una sola regla de módulo deja residual.','Contrastar reglas_pantallas y nodos; gemelos de condición/texto/parámetros por CLIENT_HOME, CLIENT_ONBOARDING, CLIENT_PAYMENTS según fuente. REEMPLAZADA solo en cobertura conjunta completa.','Verificar control 19, DPIG03=0, residual vacío y COUNT DISTINCT legacy_id.','High','activo','PR #4790 y #4794, merges 7ebe9290 y 4cbfca5b','S22-AI','LF_NUCLEO','S22-AF/AG') ON CONFLICT(codigo) DO NOTHING; IF NOT EXISTS (SELECT 1 FROM transversal.error_knowledge WHERE codigo='LF-NUCLEO-S22-SCOPE-TWINS') THEN RAISE EXCEPTION 'S22AI_EKB_MISSING LF-NUCLEO-S22-SCOPE-TWINS'; END IF; END IF; END $ekb$;
DO $ekb$ BEGIN IF to_regclass('transversal.error_knowledge') IS NOT NULL THEN INSERT INTO transversal.error_knowledge(codigo,categoria,titulo,descripcion,causa_raiz,prevencion,validacion,severidad,estado,evidencia,lote_origen,source_context,source_ref) VALUES('LF-NUCLEO-S22-PARAM-BOUNDARY-VECTORS','CI_GOVERNANCE','Pruebas relativas de frontera por parámetro','Pruebas relativas de frontera por parámetro','Control 8 rechaza valores fijos y ausencia de BAJO/EN/SOBRE_EL_LIMITE.','Usar un hecho propio por parámetro y entrada relativa param/mas; casuísticas exactas BAJO_EL_LIMITE, EN_EL_LIMITE, SOBRE_EL_LIMITE; volver a emitir hashes si cambia el paquete.','Verificar vectores y AUTO en PG17 antes de label.','High','activo','PR #4790 PASE 45749051457 y 45751164061','S22-AI','LF_NUCLEO','S22-AF/AG') ON CONFLICT(codigo) DO NOTHING; IF NOT EXISTS (SELECT 1 FROM transversal.error_knowledge WHERE codigo='LF-NUCLEO-S22-PARAM-BOUNDARY-VECTORS') THEN RAISE EXCEPTION 'S22AI_EKB_MISSING LF-NUCLEO-S22-PARAM-BOUNDARY-VECTORS'; END IF; END IF; END $ekb$;
DO $ekb$ BEGIN IF to_regclass('transversal.error_knowledge') IS NOT NULL THEN INSERT INTO transversal.error_knowledge(codigo,categoria,titulo,descripcion,causa_raiz,prevencion,validacion,severidad,estado,evidencia,lote_origen,source_context,source_ref) VALUES('LF-NUCLEO-S22-PARAM-BINDING-REPLAY','CI_GOVERNANCE','Parámetro debe existir en config y catálogo del núcleo en el replay','Parámetro debe existir en config y catálogo del núcleo en el replay','Una clave en BD real puede faltar en replay aislado o no tener fila nucleo_parametros.','En misma migración antes de propuesta sembrar config ausente sin pisar existente y registrar binding nucleo_parametros con ON CONFLICT DO NOTHING. Preflight de cada referencia y hecho.','Verificar resolución de todas las claves en PG17, no solo SELECT de producción.','High','activo','PR #4794 PASE 45753356805 y 45754211341','S22-AI','LF_NUCLEO','S22-AF/AG') ON CONFLICT(codigo) DO NOTHING; IF NOT EXISTS (SELECT 1 FROM transversal.error_knowledge WHERE codigo='LF-NUCLEO-S22-PARAM-BINDING-REPLAY') THEN RAISE EXCEPTION 'S22AI_EKB_MISSING LF-NUCLEO-S22-PARAM-BINDING-REPLAY'; END IF; END IF; END $ekb$;
